BEGIN;
CREATE TABLE IF NOT EXISTS vault_intake_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES vault_workspaces(id),requested_by uuid NOT NULL,source_kind text NOT NULL CHECK(source_kind IN('SOCIAL','MESSAGE','CLIENT','EXTERNAL_LINK','DEVICE','SCAN')),source_ref text NOT NULL,destination_folder_id uuid REFERENCES vault_folders(id),display_name text NOT NULL,state text NOT NULL DEFAULT 'RECEIVED' CHECK(state IN('RECEIVED','FETCHING','QUARANTINED','SCANNING','AWAITING_CONFIRMATION','VAULTED','BLOCKED','FAILED')),upload_id uuid REFERENCES vault_upload_sessions(id),object_id uuid REFERENCES vault_objects(id),failure_code text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,source_kind,source_ref));
CREATE TABLE IF NOT EXISTS vault_scan_results(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),intake_id uuid NOT NULL REFERENCES vault_intake_requests(id) ON DELETE CASCADE,engine text NOT NULL,verdict text NOT NULL CHECK(verdict IN('CLEAN','MALWARE','SUSPICIOUS','ERROR')),dlp_verdict text NOT NULL DEFAULT 'CLEAR' CHECK(dlp_verdict IN('CLEAR','REVIEW','BLOCK')),details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
COMMIT;
